"""Recursive-descent parser for the minisql SELECT grammar.

``parse(sql)`` returns a :class:`minisql.ast.Select`.  Every expression node
records the exact source text it was parsed from, from its first token through
its last token.
"""

from typing import List, Optional

from .ast import (
    Between,
    Binary,
    Column,
    Expr,
    FuncCall,
    InList,
    IsNull,
    Like,
    Literal,
    OrderItem,
    Select,
    SelectItem,
    Star,
    Unary,
)
from .errors import QueryError
from .lexer import RESERVED_WORDS, Token, tokenize

_COMPARISON_OPS = frozenset({"<=", ">=", "<>", "!=", "=", "<", ">"})
_ADDITIVE_OPS = frozenset({"+", "-", "||"})
_MULTIPLICATIVE_OPS = frozenset({"*", "/"})
_NOT_SUFFIXES = frozenset({"IN", "BETWEEN", "LIKE"})


class _Parser:
    def __init__(self, sql: str, tokens: List[Token]) -> None:
        self.sql = sql
        self.tokens = tokens
        self.index = 0

    # ------------------------------------------------------------------
    # Token helpers
    # ------------------------------------------------------------------
    def current(self) -> Token:
        return self.tokens[self.index]

    def peek(self, offset: int = 0) -> Token:
        idx = self.index + offset
        if idx >= len(self.tokens):
            idx = len(self.tokens) - 1
        return self.tokens[idx]

    def advance(self) -> Token:
        token = self.tokens[self.index]
        if token.kind != "EOF":
            self.index += 1
        return token

    def at_keyword(self, word: str, offset: int = 0) -> bool:
        token = self.peek(offset)
        return (
            token.kind == "IDENT"
            and not token.quoted
            and token.value.upper() == word
        )

    def at_punct(self, value: str) -> bool:
        token = self.current()
        return token.kind == "PUNCT" and token.value == value

    def at_op(self, value: str) -> bool:
        token = self.current()
        return token.kind == "OP" and token.value == value

    def expect_keyword(self, word: str) -> Token:
        if not self.at_keyword(word):
            self._error("expected {0}".format(word))
        return self.advance()

    def expect_punct(self, value: str) -> Token:
        if not self.at_punct(value):
            self._error("expected {0!r}".format(value))
        return self.advance()

    def _error(self, message: str, token: Optional[Token] = None) -> None:
        token = self.current() if token is None else token
        if token.kind == "EOF":
            raise QueryError(
                "{0} at end of query (position {1})".format(
                    message, token.start + 1
                )
            )
        snippet = self.sql[token.start : token.end]
        raise QueryError(
            "{0} at position {1}: {2!r}".format(
                message, token.start + 1, snippet
            )
        )

    def _set_text(self, node: Expr, start_index: int) -> Expr:
        """Set *node*'s text to the source spanned since *start_index*."""
        start = self.tokens[start_index].start
        end = self.tokens[self.index - 1].end
        node.text = self.sql[start:end]
        return node

    def _parse_identifier(self, what: str) -> Token:
        token = self.current()
        if token.kind != "IDENT":
            self._error("expected {0}".format(what))
        if not token.quoted and token.value.upper() in RESERVED_WORDS:
            self._error(
                "cannot use reserved keyword {0!r} as {1}".format(
                    token.value.upper(), what
                )
            )
        return self.advance()

    # ------------------------------------------------------------------
    # Query
    # ------------------------------------------------------------------
    def parse_query(self) -> Select:
        self.expect_keyword("SELECT")

        distinct = False
        if self.at_keyword("DISTINCT"):
            self.advance()
            distinct = True

        items = self._parse_select_items()

        self.expect_keyword("FROM")
        table_token = self._parse_identifier("table name")
        table = (
            table_token.value
            if table_token.quoted
            else table_token.value.lower()
        )

        where: Optional[Expr] = None
        if self.at_keyword("WHERE"):
            self.advance()
            where = self.parse_expr()

        group_by: List[Expr] = []
        if self.at_keyword("GROUP"):
            self.advance()
            self.expect_keyword("BY")
            while True:
                group_by.append(self.parse_expr())
                if self.at_punct(","):
                    self.advance()
                    continue
                break

        having: Optional[Expr] = None
        if self.at_keyword("HAVING"):
            self.advance()
            having = self.parse_expr()

        order_by: List[OrderItem] = []
        if self.at_keyword("ORDER"):
            self.advance()
            self.expect_keyword("BY")
            while True:
                expr = self.parse_expr()
                descending = False
                if self.at_keyword("ASC"):
                    self.advance()
                elif self.at_keyword("DESC"):
                    self.advance()
                    descending = True
                order_by.append(OrderItem(expr=expr, descending=descending))
                if self.at_punct(","):
                    self.advance()
                    continue
                break

        limit: Optional[int] = None
        offset: Optional[int] = None
        if self.at_keyword("LIMIT"):
            self.advance()
            limit = self._parse_integer("LIMIT")
            if self.at_keyword("OFFSET"):
                self.advance()
                offset = self._parse_integer("OFFSET")
        elif self.at_keyword("OFFSET"):
            self._error("OFFSET is only allowed after LIMIT")

        if self.at_punct(";"):
            self.advance()
            if self.current().kind != "EOF":
                self._error("unexpected token after ';'")

        if self.current().kind != "EOF":
            self._error("unexpected token")

        return Select(
            distinct=distinct,
            items=items,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def _parse_select_items(self) -> List[SelectItem]:
        if self.at_op("*"):
            token = self.advance()
            star = Star(text=self.sql[token.start : token.end])
            return [SelectItem(expr=star, alias=None)]

        items: List[SelectItem] = []
        while True:
            expr = self.parse_expr()

            alias: Optional[str] = None
            if self.at_keyword("AS"):
                self.advance()
                alias_token = self._parse_identifier("alias")
                alias = (
                    alias_token.value
                    if alias_token.quoted
                    else alias_token.value.lower()
                )
            else:
                token = self.current()
                if token.kind == "IDENT" and (
                    token.quoted
                    or token.value.upper() not in RESERVED_WORDS
                ):
                    self.advance()
                    alias = token.value if token.quoted else token.value.lower()

            items.append(SelectItem(expr=expr, alias=alias))

            if self.at_punct(","):
                self.advance()
                continue
            break

        return items

    def _parse_integer(self, what: str) -> int:
        token = self.current()
        if token.kind == "OP" and token.value == "-":
            self._error("{0} must be a non-negative integer".format(what))
        if token.kind != "NUMBER":
            self._error("expected a non-negative integer for {0}".format(what))
        if "." in token.value:
            self._error("{0} must be an integer".format(what))
        self.advance()
        return int(token.value)

    # ------------------------------------------------------------------
    # Expressions
    # ------------------------------------------------------------------
    def parse_expr(self) -> Expr:
        return self.parse_or()

    def parse_or(self) -> Expr:
        start = self.index
        left = self.parse_and()
        while self.at_keyword("OR"):
            self.advance()
            right = self.parse_and()
            left = Binary(op="OR", left=left, right=right)
            self._set_text(left, start)
        return left

    def parse_and(self) -> Expr:
        start = self.index
        left = self.parse_not()
        while self.at_keyword("AND"):
            self.advance()
            right = self.parse_not()
            left = Binary(op="AND", left=left, right=right)
            self._set_text(left, start)
        return left

    def parse_not(self) -> Expr:
        start = self.index
        if self.at_keyword("NOT"):
            self.advance()
            operand = self.parse_not()
            node = Unary(op="NOT", operand=operand)
            self._set_text(node, start)
            return node
        return self.parse_comparison()

    def parse_comparison(self) -> Expr:
        start = self.index
        left = self.parse_additive()

        while True:
            token = self.current()

            if token.kind == "IDENT" and not token.quoted:
                word = token.value.upper()

                if word == "IS":
                    self.advance()
                    negated = False
                    if self.at_keyword("NOT"):
                        self.advance()
                        negated = True
                    self.expect_keyword("NULL")
                    left = IsNull(operand=left, negated=negated)
                    self._set_text(left, start)
                    continue

                if word == "NOT" and self.peek(1).kind == "IDENT" and (
                    not self.peek(1).quoted
                    and self.peek(1).value.upper() in _NOT_SUFFIXES
                ):
                    self.advance()
                    suffix = self.current().value.upper()
                    left = self._parse_comparison_suffix(
                        left, suffix, True, start
                    )
                    continue

                if word in _NOT_SUFFIXES:
                    left = self._parse_comparison_suffix(
                        left, word, False, start
                    )
                    continue

            if token.kind == "OP" and token.value in _COMPARISON_OPS:
                self.advance()
                right = self.parse_additive()
                left = Binary(op=token.value, left=left, right=right)
                self._set_text(left, start)
                continue

            break

        return left

    def _parse_comparison_suffix(
        self, left: Expr, keyword: str, negated: bool, start: int
    ) -> Expr:
        self.expect_keyword(keyword)

        if keyword == "IN":
            self.expect_punct("(")
            items: List[Expr] = [self.parse_expr()]
            while self.at_punct(","):
                self.advance()
                items.append(self.parse_expr())
            self.expect_punct(")")
            node: Expr = InList(operand=left, items=items, negated=negated)
        elif keyword == "BETWEEN":
            low = self.parse_additive()
            self.expect_keyword("AND")
            high = self.parse_additive()
            node = Between(operand=left, low=low, high=high, negated=negated)
        else:  # LIKE
            pattern = self.parse_additive()
            node = Like(operand=left, pattern=pattern, negated=negated)

        self._set_text(node, start)
        return node

    def parse_additive(self) -> Expr:
        start = self.index
        left = self.parse_multiplicative()
        while True:
            token = self.current()
            if token.kind != "OP" or token.value not in _ADDITIVE_OPS:
                break
            op = token.value
            self.advance()
            right = self.parse_multiplicative()
            left = Binary(op=op, left=left, right=right)
            self._set_text(left, start)
        return left

    def parse_multiplicative(self) -> Expr:
        start = self.index
        left = self.parse_unary()
        while True:
            token = self.current()
            if token.kind != "OP" or token.value not in _MULTIPLICATIVE_OPS:
                break
            op = token.value
            self.advance()
            right = self.parse_unary()
            left = Binary(op=op, left=left, right=right)
            self._set_text(left, start)
        return left

    def parse_unary(self) -> Expr:
        start = self.index
        if self.at_op("-"):
            self.advance()
            operand = self.parse_unary()
            node = Unary(op="-", operand=operand)
            self._set_text(node, start)
            return node
        return self.parse_primary()

    def parse_primary(self) -> Expr:
        token = self.current()

        if token.kind == "NUMBER":
            self.advance()
            text = self.sql[token.start : token.end]
            if "." in token.value:
                value = float(token.value)
            else:
                value = int(token.value)
            return Literal(text=text, value=value)

        if token.kind == "STRING":
            self.advance()
            return Literal(
                text=self.sql[token.start : token.end], value=token.value
            )

        if token.kind == "IDENT":
            word = token.value.upper() if not token.quoted else None

            if word == "NULL":
                self.advance()
                return Literal(
                    text=self.sql[token.start : token.end], value=None
                )
            if word == "TRUE":
                self.advance()
                return Literal(
                    text=self.sql[token.start : token.end], value=True
                )
            if word == "FALSE":
                self.advance()
                return Literal(
                    text=self.sql[token.start : token.end], value=False
                )

            if (
                not token.quoted
                and word not in RESERVED_WORDS
                and self.peek(1).kind == "PUNCT"
                and self.peek(1).value == "("
            ):
                return self._parse_func_call()

            if not token.quoted and word in RESERVED_WORDS:
                self._error(
                    "unexpected keyword {0!r}".format(word)
                )

            self.advance()
            return Column(
                name=token.value.lower(),
                text=self.sql[token.start : token.end],
            )

        if token.kind == "PUNCT" and token.value == "(":
            start = self.index
            self.advance()
            inner = self.parse_expr()
            rparen = self.expect_punct(")")
            inner.text = self.sql[self.tokens[start].start : rparen.end]
            return inner

        if token.kind == "OP" and token.value == "*":
            self._error("unexpected '*'; '*' is only allowed in SELECT * or COUNT(*)")

        self._error("unexpected token")

    def _parse_func_call(self) -> FuncCall:
        start = self.index
        name_token = self.advance()
        self.expect_punct("(")

        args: List[Expr] = []
        star = False

        if self.at_op("*"):
            self.advance()
            star = True
            self.expect_punct(")")
        elif self.at_punct(")"):
            self.advance()
        else:
            while True:
                args.append(self.parse_expr())
                if self.at_punct(","):
                    self.advance()
                    continue
                break
            self.expect_punct(")")

        node = FuncCall(
            name=name_token.value.upper(), args=args, star=star
        )
        self._set_text(node, start)
        return node


def parse(sql: str) -> Select:
    """Parse *sql* and return a :class:`minisql.ast.Select`.

    Raises :class:`minisql.errors.QueryError` on any syntax error.
    """
    tokens = tokenize(sql)
    return _Parser(sql, tokens).parse_query()

